    section: "Topic 9(ii)", questionRef: "2021 HL Topic 9(ii) Q(b)",
    questionText: "Describe how, according to Socrates, the primitive community developed into a “civilized community”.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 20,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Glaucon says that this society would be too basic, so Socrates says that typically, we go on to improve our standards to include more refined and luxurious items (food, furniture, perfume... etc.)", marks: null, openList: true },
    { id: "r-2", kind: "point", verbatim: "This, in turn leads to the formation of larger cities, bigger communities and the need for more land", marks: null, openList: true },
    { id: "r-3", kind: "point", verbatim: "It also leads to a greater specialisation and sophistication", marks: null, openList: true },
    { id: "r-4", kind: "point", verbatim: "This, in turn, leads to a variety of professions and trades", marks: null, openList: true },
    ],
