    questionText: "Why does Socrates believe that war is inevitable in the civilised community?",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 10,
    rows: [
    { id: "r-1", kind: "point", verbatim: "The growth of large cities means there is a greater demand for food and other goods, this leads to a desire for more land (which belongs to one’s neighbour and has to be fought for)", marks: null },
    { id: "r-2", kind: "point", verbatim: "It also ends up in competition with neighbouring communities for trade", marks: null },
    { id: "r-3", kind: "point", verbatim: "Hence the need for armies and the inevitable outbreak of wars", marks: null },
    ],
