    tariffModel: {"kind":"questionTotal"}, totalMarks: 35,
    rows: [
    { id: "r-1", kind: "point", verbatim: "This is a typical Hellenistic sculpture in every way", marks: null },
    { id: "r-2", kind: "point", verbatim: "Firstly, its subject matter is different to typical sculpture of previous eras", marks: null },
    { id: "r-3", kind: "point", verbatim: "Its subject is a non-Greek", marks: null },
    { id: "r-4", kind: "point", verbatim: "He is definitely Gallic, tall, wearing a torc and with typical Celtic moustache and gelled-back hair", marks: null },
    { id: "r-5", kind: "point", verbatim: "He is also dying, which is evidence of the Hellenistic fashion for the revelation of emotion and the emphasis on high drama", marks: null },
    { id: "r-6", kind: "point", verbatim: "The body, just at the point of collapse, barely held up on one hand is in extremis", marks: null },
    { id: "r-7", kind: "point", verbatim: "The exhausted limbs carved in very realistic detail, even veins show up, are exhausted and the drooping, but noble head shows the end is near", marks: null },
    { id: "r-8", kind: "point", verbatim: "His face is full of strain and tiredness, but he is heroic in defeat", marks: null },
    { id: "r-9", kind: "point", verbatim: "His abandoned horn shows his role in the battle", marks: null },
    { id: "r-10", kind: "point", verbatim: "The contortion and pain in the body and face, the drama and theatricality of the moment and the choice of a different physical type, (ie. non-Greek), are all typical of the period", marks: null },
    ],
